// vga_controller.v
// 640x480 @ 60 Hz timing for the DE1-SoC VGA DAC (ADV7123).
// Pixel clock = 25 MHz, generated by dividing CLOCK_50 by 2.
//
// Usage: feed back (x, y) into a combinational pixel renderer, connect its
// colour to r_in/g_in/b_in. This module registers sync, blank and colour
// together, so everything stays aligned on the same pixel.
//
//   Horizontal: 640 visible | 16 front porch | 96 sync | 48 back porch = 800
//   Vertical  : 480 visible | 10 front porch |  2 sync | 33 back porch = 525

module vga_controller (
    input            clk,        // CLOCK_50
    input            reset,      // active-high, synchronous
    input      [7:0] r_in,
    input      [7:0] g_in,
    input      [7:0] b_in,
    output     [9:0] x,          // current pixel column (0..799)
    output     [9:0] y,          // current pixel row    (0..524)
    output reg       frame_start, // 1-cycle pulse at the top of each frame
    output reg [7:0] VGA_R,
    output reg [7:0] VGA_G,
    output reg [7:0] VGA_B,
    output reg       VGA_HS,
    output reg       VGA_VS,
    output reg       VGA_BLANK_N,
    output           VGA_SYNC_N,
    output           VGA_CLK
);

    localparam H_VISIBLE = 10'd640;
    localparam H_FP      = 10'd16;
    localparam H_SYNC    = 10'd96;
    localparam H_TOTAL   = 10'd800;
    localparam V_VISIBLE = 10'd480;
    localparam V_FP      = 10'd10;
    localparam V_SYNC    = 10'd2;
    localparam V_TOTAL   = 10'd525;

    // 25 MHz pixel clock. Registers update on the 50 MHz edge where pclk
    // falls, so data is stable for a full 20 ns before VGA_CLK rises.
    reg pclk;
    wire pix_en = pclk;

    reg [9:0] hcount;
    reg [9:0] vcount;

    assign x = hcount;
    assign y = vcount;
    assign VGA_CLK    = pclk;
    assign VGA_SYNC_N = 1'b0;   // sync-on-green not used

    always @(posedge clk) begin
        if (reset)
            pclk <= 1'b0;
        else
            pclk <= ~pclk;
    end

    // counters
    always @(posedge clk) begin
        if (reset) begin
            hcount <= 10'd0;
            vcount <= 10'd0;
        end
        else if (pix_en) begin
            if (hcount == H_TOTAL - 10'd1) begin
                hcount <= 10'd0;
                if (vcount == V_TOTAL - 10'd1)
                    vcount <= 10'd0;
                else
                    vcount <= vcount + 10'd1;
            end
            else begin
                hcount <= hcount + 10'd1;
            end
        end
    end

    // combinational sync/visible flags for the CURRENT counter values
    reg hs_now, vs_now, visible_now;
    always @(*) begin
        hs_now = 1'b1;
        if (hcount >= H_VISIBLE + H_FP && hcount < H_VISIBLE + H_FP + H_SYNC)
            hs_now = 1'b0;             // active-low

        vs_now = 1'b1;
        if (vcount >= V_VISIBLE + V_FP && vcount < V_VISIBLE + V_FP + V_SYNC)
            vs_now = 1'b0;             // active-low

        visible_now = 1'b0;
        if (hcount < H_VISIBLE && vcount < V_VISIBLE)
            visible_now = 1'b1;
    end

    // output register stage (one pixel of latency on everything = aligned)
    always @(posedge clk) begin
        if (reset) begin
            VGA_HS      <= 1'b1;
            VGA_VS      <= 1'b1;
            VGA_BLANK_N <= 1'b0;
            VGA_R       <= 8'd0;
            VGA_G       <= 8'd0;
            VGA_B       <= 8'd0;
            frame_start <= 1'b0;
        end
        else begin
            frame_start <= 1'b0;
            if (pix_en) begin
                VGA_HS      <= hs_now;
                VGA_VS      <= vs_now;
                VGA_BLANK_N <= visible_now;
                if (visible_now) begin
                    VGA_R <= r_in;
                    VGA_G <= g_in;
                    VGA_B <= b_in;
                end
                else begin
                    VGA_R <= 8'd0;
                    VGA_G <= 8'd0;
                    VGA_B <= 8'd0;
                end
                if (hcount == 10'd0 && vcount == 10'd0)
                    frame_start <= 1'b1;
            end
        end
    end

endmodule
